/**
 * The system-prompt preamble: the identity line for THIS task, then the persona itself.
 *
 * @param {string} taskRole  what this particular call is doing, e.g. 'the analysis engine of the
 *                           IntMap world map'. It completes the sentence "You are Atlas, …".
 * @param {{mode?: 'full'|'internal'}} [opts]  'internal' for a call whose whole output is machine-read.
 * @returns {string} the preamble, ending in a newline so the caller appends its task rules directly.
 */
export function personaPrompt(taskRole, opts) {
  const P = personaPrompt.spec;
  const ids = (opts && opts.mode === 'internal') ? P.internal : P.order;
  const role = String(taskRole == null ? '' : taskRole).trim().replace(/[.\s]+$/, '');
  return 'You are ' + P.name + (role ? ', ' + role : '') + '.\n'
    + P.heading + '\n'
    + ids.map((id) => '· ' + P.clauses[id]).join('\n') + '\n';
}

